using System.IO;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TekstilCAD.Core;
using TekstilCAD.FileFormats;

internal sealed class Experiment {
 public required string Format {get;set;} public required int Version {get;set;} public required string Unit {get;set;} public required string Purpose {get;set;}
 public required bool Transferable {get;set;} public required bool TopologyVerified {get;set;} public required bool LicenseVerified {get;set;}
 public required List<string> Omissions {get;set;} public required List<Piece> Pieces {get;set;}
}
internal sealed class Piece { public required string Id {get;set;} public required List<Command> Commands {get;set;} public required List<Mark> Marks {get;set;} }
internal sealed class Command { public required string Kind {get;set;} public required List<double[]> Points {get;set;} }
internal sealed class Mark { public required string Name {get;set;} public required string Shape {get;set;} public required double[] Matrix {get;set;} }
internal static class Codec {
 static readonly JsonSerializerOptions Options=new(){PropertyNamingPolicy=JsonNamingPolicy.CamelCase,UnmappedMemberHandling=JsonUnmappedMemberHandling.Disallow,MaxDepth=32};
 static readonly string[] Roles=["breanna.front","breanna.back","breanna.sleeve"], Losses=["allowance","grainline","cutlist","source-svg-style","production-boundary"];
 static void Unique(JsonElement e){if(e.ValueKind==JsonValueKind.Object){var names=new HashSet<string>(StringComparer.Ordinal);foreach(var p in e.EnumerateObject()){if(!names.Add(p.Name))throw new InvalidDataException("Duplicate field");Unique(p.Value);}}else if(e.ValueKind==JsonValueKind.Array)foreach(var item in e.EnumerateArray())Unique(item);}
 public static Experiment Read(byte[] bytes){if(bytes.Length==0||bytes.Length>1_000_000)throw new InvalidDataException("Size");try{using var json=JsonDocument.Parse(bytes,new JsonDocumentOptions{MaxDepth=32});Unique(json.RootElement);var result=JsonSerializer.Deserialize<Experiment>(bytes,Options)??throw new InvalidDataException("Empty");Validate(result);return result;}catch(JsonException e){throw new InvalidDataException("Invalid experimental document",e);}}
 public static byte[] Write(Experiment doc){Validate(doc);var bytes=JsonSerializer.SerializeToUtf8Bytes(doc,Options);if(bytes.Length>1_000_000)throw new InvalidDataException("Size");return bytes;}
 public static void Validate(Experiment doc){if(doc.Format!="tekstilcad.synthetic.wpf-curves"||doc.Version!=1||doc.Unit!="mm"||doc.Purpose!="diagnostic-only"||doc.Transferable||doc.TopologyVerified||doc.LicenseVerified||doc.Omissions is null||!doc.Omissions.SequenceEqual(Losses)||doc.Pieces is null||doc.Pieces.Count!=3||doc.Pieces.Select(x=>x.Id).Distinct(StringComparer.Ordinal).Count()!=3||doc.Pieces.Any(x=>!Roles.Contains(x.Id,StringComparer.Ordinal)))throw new InvalidDataException("Contract");int total=0;foreach(var p in doc.Pieces){if(p.Commands is null||p.Commands.Count<3||p.Commands.Count>4096||(total+=p.Commands.Count)>8192||p.Commands[0].Kind!="move"||p.Commands[^1].Kind!="close")throw new InvalidDataException("Path");for(int i=0;i<p.Commands.Count;i++){var c=p.Commands[i];int count=c.Kind switch {"move" or "line"=>1,"curve"=>3,"close"=>0,_=>-1};if(c.Points is null||count<0||c.Points.Count!=count||c.Points.Any(q=>!Point(q))||c.Kind=="move"&&i!=0||c.Kind=="close"&&i!=p.Commands.Count-1)throw new InvalidDataException("Path operation");}if(p.Marks is null||p.Marks.Count is <1 or >4||p.Marks.Select(m=>m.Name).Distinct(StringComparer.Ordinal).Count()!=p.Marks.Count)throw new InvalidDataException("Marks");foreach(var m in p.Marks){var allowed=p.Id switch {"breanna.front"=>m.Name is "bustNotch" or "armholePitch"&&m.Shape=="notch","breanna.back"=>m.Name=="armholePitch"&&m.Shape=="bnotch","breanna.sleeve"=>m.Name=="frontNotch"&&m.Shape=="notch"||m.Name=="backNotch"&&m.Shape=="bnotch",_=>false};if(!allowed||m.Matrix is null||m.Matrix.Length!=6||m.Matrix.Any(v=>!Finite(v))||!Finite(m.Matrix[0]*m.Matrix[3]-m.Matrix[1]*m.Matrix[2])||Math.Abs(m.Matrix[0]*m.Matrix[3]-m.Matrix[1]*m.Matrix[2])<1e-12)throw new InvalidDataException("Mark");}int required=p.Id=="breanna.back"?1:2;if(p.Marks.Count!=required)throw new InvalidDataException("Missing mark");}}
 static bool Point(double[] q)=>q is not null&&q.Length==2&&q.All(Finite);static bool Finite(double x)=>double.IsFinite(x)&&Math.Abs(x)<=1e8;
}
internal static class Preview {
 public static DrawingVisual Build(Experiment doc){Codec.Validate(doc);const double width=1100,height=760,pad=35,header=55;var pts=doc.Pieces.SelectMany(p=>p.Commands).SelectMany(c=>c.Points).Concat(doc.Pieces.SelectMany(p=>p.Marks).SelectMany(GlyphCorners)).ToArray();double minX=pts.Min(q=>q[0]),maxX=pts.Max(q=>q[0]),minY=pts.Min(q=>q[1]),maxY=pts.Max(q=>q[1]);if(maxX<=minX||maxY<=minY)throw new InvalidDataException("Bounds");double scale=Math.Min((width-2*pad)/(maxX-minX),(height-header-2*pad)/(maxY-minY));var visual=new DrawingVisual();using var dc=visual.RenderOpen();dc.DrawRectangle(Brushes.White,null,new Rect(0,0,width,height));dc.DrawText(new FormattedText("SENTETİK · TOPOLOJİ VE LİSANS DOĞRULANMADI · ÜRETİM İÇİN DEĞİLDİR",System.Globalization.CultureInfo.GetCultureInfo("tr-TR"),FlowDirection.LeftToRight,new Typeface("Segoe UI"),15,Brushes.DarkRed,1),new Point(20,16));dc.PushTransform(new MatrixTransform(scale,0,0,scale,pad-minX*scale,header+pad-minY*scale));var pen=new Pen(Brushes.DarkSlateBlue,1.4/scale);var markPen=new Pen(Brushes.DarkMagenta,.7/scale);foreach(var p in doc.Pieces){var geometry=GeometryFor(p);dc.DrawGeometry(null,pen,geometry);foreach(var m in p.Marks){var a=m.Matrix;dc.PushTransform(new MatrixTransform(a[0],a[1],a[2],a[3],a[4],a[5]));dc.DrawEllipse(null,markPen,new Point(0,0),2.8,2.8);if(m.Shape=="notch")dc.DrawEllipse(Brushes.DarkMagenta,null,new Point(0,0),1.4,1.4);else{dc.DrawLine(markPen,new Point(-1.1,-1.1),new Point(1.1,1.1));dc.DrawLine(markPen,new Point(1.1,-1.1),new Point(-1.1,1.1));}dc.Pop();}}dc.Pop();return visual;}
 static IEnumerable<double[]> GlyphCorners(Mark m){foreach(double x in new[]{-2.8,2.8})foreach(double y in new[]{-2.8,2.8}){var a=m.Matrix;double u=a[0]*x+a[2]*y+a[4],v=a[1]*x+a[3]*y+a[5];if(!double.IsFinite(u)||!double.IsFinite(v)||Math.Abs(u)>1e8||Math.Abs(v)>1e8)throw new InvalidDataException("Glyph bounds");yield return [u,v];}}
 static PathGeometry GeometryFor(Piece p){var f=new PathFigure{StartPoint=Pt(p.Commands[0].Points[0]),IsClosed=true,IsFilled=false};foreach(var c in p.Commands.Skip(1)){if(c.Kind=="line")f.Segments.Add(new LineSegment(Pt(c.Points[0]),true));else if(c.Kind=="curve")f.Segments.Add(new BezierSegment(Pt(c.Points[0]),Pt(c.Points[1]),Pt(c.Points[2]),true));}var g=new PathGeometry();g.Figures.Add(f);return g;}
 public static void VerifyGeometry(Experiment doc){foreach(var p in doc.Pieces){var f=GeometryFor(p).Figures.Single();if(!f.IsClosed||f.StartPoint!=Pt(p.Commands[0].Points[0]))throw new InvalidDataException("Renderer closure");var commands=p.Commands.Where(c=>c.Kind is "line" or "curve").ToArray();if(commands.Length!=f.Segments.Count)throw new InvalidDataException("Renderer segments");for(int i=0;i<commands.Length;i++){var c=commands[i];if(c.Kind=="curve"){if(f.Segments[i] is not BezierSegment b||b.Point1!=Pt(c.Points[0])||b.Point2!=Pt(c.Points[1])||b.Point3!=Pt(c.Points[2]))throw new InvalidDataException("Renderer cubic");}else if(f.Segments[i] is not LineSegment l||l.Point!=Pt(c.Points[0]))throw new InvalidDataException("Renderer line");}}}
 static Point Pt(double[] a)=>new(a[0],a[1]);
 public static byte[] Render(Experiment doc){var bmp=new RenderTargetBitmap(1100,760,96,96,PixelFormats.Pbgra32);bmp.Render(Build(doc));var enc=new PngBitmapEncoder();enc.Frames.Add(BitmapFrame.Create(bmp));using var stream=new MemoryStream();enc.Save(stream);return stream.ToArray();}
}
internal static class Program {
 [STAThread] static int Main(){try{using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(3));using var buffer=new MemoryStream();var input=Console.OpenStandardInput();var chunk=new byte[8192];while(true){int n=Task.Run(()=>input.Read(chunk,0,chunk.Length)).WaitAsync(timeout.Token).GetAwaiter().GetResult();if(n==0)break;if(buffer.Length+n>1_000_000)throw new InvalidDataException("Input too large");buffer.Write(chunk,0,n);}var inputBytes=buffer.ToArray();var doc=Codec.Read(inputBytes);var encoded=Codec.Write(doc);var roundtrip=Codec.Read(encoded);if(!encoded.SequenceEqual(Codec.Write(roundtrip)))throw new InvalidDataException("Roundtrip");var root=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../runtime"));Directory.CreateDirectory(root);string id=Guid.NewGuid().ToString("N"),v1=Path.Combine(root,id+"-experiment.json"),legacy=Path.Combine(root,id+"-legacy.json"),legacyV1=Path.Combine(root,id+"-legacy-v1.json"),image=Path.Combine(root,id+"-preview.png");bool madeV1=false,madeLegacy=false,madeLegacyV1=false;try{using(var file=new FileStream(v1,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeV1=true;file.Write(encoded);}if(!Codec.Write(Codec.Read(File.ReadAllBytes(v1))).SequenceEqual(encoded))throw new InvalidDataException("File roundtrip");var old=new ProjectDocument{Name="Synthetic legacy",Pieces=[new PatternPiece{Name="Synthetic triangle",Points=[new(0,0),new(10,0),new(0,10)],Closed=true}]};using(var reserved=new FileStream(legacy,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeLegacy=true;}ProjectStorage.Save(old,legacy);var loaded=ProjectStorage.Load(legacy);if(loaded.Pieces.Count!=1||!loaded.Pieces[0].Points.SequenceEqual(old.Pieces[0].Points)||!loaded.Pieces[0].Closed)throw new InvalidDataException("Legacy read");var legacyText=File.ReadAllText(legacy);using(var f=new FileStream(legacyV1,FileMode.CreateNew,FileAccess.Write,FileShare.None)){madeLegacyV1=true;using var w=new StreamWriter(f,new UTF8Encoding(false));w.Write("[1,"+legacyText+"]");}var loadedV1=ProjectStorage.Load(legacyV1);if(!loadedV1.Pieces[0].Points.SequenceEqual(old.Pieces[0].Points))throw new InvalidDataException("Legacy v1 read");bool legacyRejected=false;try{ProjectStorage.Load(v1);}catch(InvalidDataException){legacyRejected=true;}if(!legacyRejected)throw new InvalidDataException("Production reader accepted experiment");Preview.VerifyGeometry(roundtrip);var png=Preview.Render(roundtrip);if(png.Length<2000)throw new InvalidDataException("Preview empty");using(var f=new FileStream(image,FileMode.CreateNew,FileAccess.Write,FileShare.None))f.Write(png);Console.Write(JsonSerializer.Serialize(new {status="PASS",preview=image,legacyRead=true,legacyV1Read=true,productionReaderRejected=true,pieces=roundtrip.Pieces.Count,curves=roundtrip.Pieces.Sum(p=>p.Commands.Count(c=>c.Kind=="curve")),marks=roundtrip.Pieces.Sum(p=>p.Marks.Count),productionApproved=false}));}finally{if(madeV1&&File.Exists(v1))File.Delete(v1);if(madeLegacy&&File.Exists(legacy))File.Delete(legacy);if(madeLegacyV1&&File.Exists(legacyV1))File.Delete(legacyV1);}}catch{Console.Error.Write("INVALID_SYNTHETIC_DOCUMENT");return 1;}return 0;}
}
